mapper.update:
update biz_monthly_usage
set budget_amount = #{budgetAmount},
    reserved_amount = reserved_amount + #{reserveAmount},
    update_time = sysdate()
where company_id = #{companyId}
  and billing_month = #{billingMonth}
  and status = '0'
  and used_amount + reserved_amount + #{reserveAmount} <= #{budgetAmount}

update biz_monthly_usage
set reserved_amount = greatest(reserved_amount - #{reserveAmount}, 0),
    used_amount = used_amount + #{actualAmount},
    update_time = sysdate()
where company_id = #{companyId}
  and billing_month = #{billingMonth}

update biz_monthly_usage
set reserved_amount = greatest(reserved_amount - #{reserveAmount}, 0),
    update_time = sysdate()
where company_id = #{companyId}
  and billing_month = #{billingMonth}
